                                       const char splitter) {
  std::vector<std::string_view> result{};

  u64 last = 0;
  u64 curr = 0;
  for (; curr < input.size(); curr++) {
    if (input[curr] == splitter) {
      result.push_back(std::string_view(input).substr(last, curr - last));
      last = curr + 1;
    }
  }

  if (curr != last) {
    result.push_back(std::string_view(input).substr(last, curr - last));
  }

  return result;
}

