459	void Feather::print_tree(Entry *entry, u64 depth) {
460	  auto print_indent = [depth]() {
461	    for (u64 i = 0; i < depth; i++) {
462	      printf("  ");
463	    }
464	  };
465	
466	  switch (entry->type) {
467	  case Segment_Type::Directory: {
468	    print_indent();
469	    printf("%s/\n", entry->name.c_str());
470	    for (auto child : entry->directory().entries) {
471	      print_tree(child, depth + 1);
472	    }
473	    break;
474	  }
475	  case Segment_Type::File: {
476	    print_indent();
477	    printf("%s: File, %zu bytes\n", entry->name.c_str(),
478	           entry->file().contents.size());
479	    break;
480	  }
481	  case Segment_Type::File_Clone: {
482	    print_indent();
483	    printf("%s: File, %zu bytes\n", entry->name.c_str(),
484	           entry->file_clone(*this).cached_file_contents.size());
485	    break;
486	  }
487	  case Segment_Type::Symlink: {
488	    print_indent();
489	    auto &symlink = entry->symlink(*this);
490	    std::string target_name = symlink.target;
491	    if (symlink.target_inode_cache == nullptr) {
492	      target_name += " (broken)";
493	    }
494	    printf("%s: Symlink to %s\n", entry->name.c_str(), target_name.c_str());
495	    break;
496	  }
497	  case Segment_Type::Hardlink: {
498	    auto &hardlink = entry->hardlink(*this);
499	    print_tree(hardlink.target_inode_cache, depth);
500	    break;
501	  }
502	  default: {
503	    printf("Error: Unhandled segment type in print_tree: %#x\n",
504	           u32(entry->type));
505	    abort();
506	  }
507	  }
