 17	std::vector<u8> base64_decode(const std::string &encoded) {
 18	  std::vector<int> T(256, -1);
 19	  for (int i = 0; i < 64; i++) {
 20	    T["ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"[i]] =
 21	        i;
 22	  }
 23	
 24	  std::vector<u8> out{};
 25	
 26	  int val = 0, valb = -8;
 27	  for (auto c : encoded) {
 28	    if (T[c] == -1)
 29	      break;
 30	    val = (val << 6) + T[c];
 31	    valb += 6;
 32	    if (valb >= 0) {
 33	      out.push_back(char((val >> valb) & 0xFF));
 34	      valb -= 8;
 35	    }
 36	  }
 37	
 38	  return out;
 39	}
