 60	std::vector<std::string_view> split_by(const std::string &input,
 61	                                       const char splitter) {
 62	  std::vector<std::string_view> result{};
 63	
 64	  u64 last = 0;
 65	  u64 curr = 0;
 66	  for (; curr < input.size(); curr++) {
 67	    if (input[curr] == splitter) {
 68	      result.push_back(std::string_view(input).substr(last, curr - last));
 69	      last = curr + 1;
 70	    }
 71	  }
 72	
 73	  if (curr != last) {
 74	    result.push_back(std::string_view(input).substr(last, curr - last));
 75	  }
 76	
 77	  return result;
 78	}
