156	  Symlink &symlink(Feather &fs) {
157	    auto &result = std::get<Symlink>(value);
158	    if (result.target_inode_cache == nullptr) {
159	      const auto components = split_by(result.target, '/');
160	      Entry *curr = fs.root;
161	      for (u64 i = 0; i < components.size() - 1; i++) {
162	        const auto &component = components[i];
163	        const auto &next_component = components[i + 1];
164	        if (curr->name != component) {
165	          goto end;
166	        }
167	        switch (curr->type) {
168	        case Segment_Type::Directory: {
169	          const auto &directory = curr->directory();
170	          const auto it = std::find_if(
171	              directory.entries.begin(), directory.entries.end(),
172	              [&](Entry *entry) { return entry->name == next_component; });
173	          if (it == directory.entries.end()) {
174	            goto end;
175	          }
176	          curr = *it;
177	          break;
178	        }
179	        case Segment_Type::File: {
180	          goto end;
181	        }
182	        case Segment_Type::File_Clone: {
183	          goto end;
184	        }
185	        case Segment_Type::Symlink: {
