41: static std::string encoded{};
42: std::vector<u8> read_base64_from_stdin() {
43:   char buffer[256] = {0};
44: 
45:   encoded = "";
46: 
47:   ssize_t read_amount = 0;
48:   while ((read_amount = read(STDIN_FILENO, buffer, sizeof(buffer))) > 0) {
49:     encoded += std::string(buffer, read_amount);
50: 
51:     if (encoded.size() > 2 && encoded[encoded.size() - 1] == '\n' &&
52:         encoded[encoded.size() - 2] == '\n') {
53:       break;
54:     }
55:   }
56: 
57:   return base64_decode(encoded);
58: }
