122: 
123:   static Entry *make_directory(const std::string_view name,
124:                                const std::vector<Entry *> &entries) {
125:     return new Entry{Segment_Type::Directory, std::string(name),
126:                      Directory{entries}};
127:   }
128:   static Entry *make_file(const std::string_view name,
129:                           const std::vector<u8> &contents) {
130:     return new Entry{Segment_Type::File, std::string(name), File{contents}};
131:   }
132:   static Entry *make_file_clone(const std::string_view name, u32 source) {
133:     return new Entry{Segment_Type::File_Clone, std::string(name),
134:                      File_Clone{source, {}}};
135:   }
136:   static Entry *make_symlink(const std::string_view name,
137:                              const std::string_view target) {
138:     return new Entry{Segment_Type::Symlink, std::string(name),
139:                      Symlink{std::string(target), nullptr}};
140:   }
141:   static Entry *make_hardlink(const std::string_view name, u32 target) {
142:     return new Entry{Segment_Type::Hardlink, std::string(name),
143:                      Hardlink{target, nullptr}};
