146:   Directory &directory() { return std::get<Directory>(value); }
147:   File &file() { return std::get<File>(value); }
148:   File_Clone &file_clone(Feather &fs) {
149:     auto &result = std::get<File_Clone>(value);
150:     if (result.cached_file_contents.empty()) {
151:       result.cached_file_contents =
