261: template <typename T>
262: std::span<T> checked_subspan(const std::span<T> span, u64 offset, u64 length) {
263:   if (offset <= span.size() && offset + length <= span.size() &&
264:       offset <= offset + length) {
265:     return span.subspan(offset, length);
266:   }
267:   printf("Invalid subspan for span of size %zu: offset: %zu, length: %zu\n",
268:          span.size(), offset, length);
269:   abort();
270: }
