272: Feather load_feather_fs(const std::vector<u8> &blob) {
273:   if (blob.size() < sizeof(layout::Header)) {
274:     printf("Filesystem blob too small!\n");
275:     abort();
276:   }
277: 
278:   const auto &header = *(const layout::Header *)(blob.data());
279: 
280:   if (header.magic != 0x52454854414546) {
281:     printf("Invalid magic: %llx\n", header.magic);
282:     abort();
283:   }
284:   if (header.num_segments > 100000) {
285:     printf("Too many segments: %zu (max: 100000)\n", header.num_segments);
286:     abort();
287:   }
288:   if (sizeof(layout::Header) + header.num_segments * sizeof(layout::Segment) >
289:       blob.size()) {
290:     printf("Segment table size is larger than size of blob\n");
291:     abort();
292:   }
293: 
294:   const auto *segment_region =
295:       (const layout::Segment *)(blob.data() + sizeof(layout::Header));
296:   std::span<const layout::Segment> segments(segment_region,
297:                                             header.num_segments);
298: 
299:   const auto *data_region = (const u8 *)&segment_region[header.num_segments];
300:   std::span<const u8> data(data_region, blob.data() + blob.size());
301: 
302:   u64 total_segments = std::count_if(
303:       segments.begin(), segments.end(), [](layout::Segment segment) {
304:         return segment.type != u32(Segment_Type::Label);
305:       });
306: 
307:   Feather feather{};
308:   while (feather.loaded_segments.size() != total_segments) {
309:     for (const auto &segment : segments) {
310:       if (feather.loaded_segments.contains(segment.id)) {
311:         continue;
312:       }
313: 
314:       auto contents = checked_subspan(data, segment.offset, segment.length);
315: 
316:       switch (segment.type) {
317:       case u32(Segment_Type::Directory): {
318:         if (segment.length < sizeof(layout::Directory)) {
319:           printf("Directory segment too small (%u vs %u)\n", segment.length,
320:                  sizeof(layout::Directory));
321:           abort();
322:         }
323: 
324:         const auto &directory_header =
325:             *(const layout::Directory *)(contents.data());
326:         std::span<const u8> name = checked_subspan(
327:             contents, sizeof(layout::Directory), directory_header.name_length);
328:         std::span<const u8> children_bytes = checked_subspan(
329:             contents, sizeof(layout::Directory) + directory_header.name_length,
330:             directory_header.num_entries * sizeof(u32));
331:         std::span<const u32> children((const u32 *)children_bytes.data(),
332:                                       children_bytes.size() / sizeof(u32));
333: 
334:         std::vector<Entry *> child_entries{};
335:         child_entries.reserve(children.size());
336:         bool missing_children = false;
337:         for (const auto child : children) {
338:           if (!feather.loaded_segments.contains(child)) {
339:             missing_children = true;
340:             break;
341:           }
342:           child_entries.push_back(feather.loaded_segments[child]);
343:         }
344:         if (missing_children) {
345:           continue;
346:         }
347: 
348:         feather.loaded_segments[segment.id] = Entry::make_directory(
349:             std::string_view((const char *)name.data(), name.size()),
350:             child_entries);
351:         if (name.empty()) {
352:           feather.root = feather.loaded_segments[segment.id];
353:         }
354:         break;
355:       }
356:       case u32(Segment_Type::File): {
357:         if (segment.length < sizeof(layout::File)) {
358:           printf("File segment too small (%u vs %u)\n", segment.length,
359:                  sizeof(layout::File));
360:           abort();
361:         }
362: 
363:         const auto &file_header = *(const layout::File *)(contents.data());
364:         std::span<const u8> name = checked_subspan(
365:             contents, sizeof(layout::File), file_header.name_length);
366:         std::span<const u8> file_contents = checked_subspan(
367:             contents, sizeof(layout::File) + file_header.name_length,
368:             file_header.contents_length);
369: 
370:         feather.loaded_segments[segment.id] = Entry::make_file(
371:             std::string_view((const char *)name.data(), name.size()),
372:             std::vector<u8>(file_contents.data(),
373:                             file_contents.data() + file_contents.size()));
374:         break;
375:       }
376:       case u32(Segment_Type::File_Clone): {
377:         if (segment.length < sizeof(layout::File_Clone)) {
378:           printf("File_Clone segment too small (%u vs %u)\n", segment.length,
379:                  sizeof(layout::File_Clone));
380:           abort();
381:         }
382: 
383:         const auto &file_clone_header =
384:             *(const layout::File_Clone *)(contents.data());
385:         std::span<const u8> name =
386:             checked_subspan(contents, sizeof(layout::File_Clone),
387:                             file_clone_header.name_length);
388:         auto target = file_clone_header.target_inode;
389: 
390:         if (!feather.loaded_segments.contains(target)) {
391:           continue;
392:         }
393: 
394:         feather.loaded_segments[segment.id] = Entry::make_file_clone(
395:             std::string_view((const char *)name.data(), name.size()), target);
396:         break;
397:       }
398:       case u32(Segment_Type::Symlink): {
399:         if (segment.length < sizeof(layout::Symlink)) {
400:           printf("Symlink segment too small (%u vs %u)\n", segment.length,
401:                  sizeof(layout::Symlink));
402:           abort();
403:         }
404: 
405:         const auto &symlink_header =
406:             *(const layout::Symlink *)(contents.data());
407:         std::span<const u8> name = checked_subspan(
408:             contents, sizeof(layout::Symlink), symlink_header.name_length);
409:         std::span<const u8> target = checked_subspan(
410:             contents, sizeof(layout::Symlink) + symlink_header.name_length,
411:             symlink_header.target_length);
412: 
413:         feather.loaded_segments[segment.id] = Entry::make_symlink(
414:             std::string_view((const char *)name.data(), name.size()),
415:             std::string_view((const char *)target.data(), target.size()));
416:         break;
417:       }
418:       case u32(Segment_Type::Hardlink): {
419:         if (segment.length < sizeof(layout::Hardlink)) {
420:           printf("Hardlink segment too small (%u vs %u)\n", segment.length,
421:                  sizeof(layout::Hardlink));
422:           abort();
423:         }
424: 
425:         const auto &hardlink_header =
426:             *(const layout::Hardlink *)(contents.data());
427:         std::span<const u8> name = checked_subspan(
428:             contents, sizeof(layout::Hardlink), hardlink_header.name_length);
429: 
430:         feather.loaded_segments[segment.id] = Entry::make_hardlink(
431:             std::string_view((const char *)name.data(), name.size()),
432:             hardlink_header.target);
433:         break;
434:       }
435:       case u32(Segment_Type::Label): {
436:         feather.label.assign(
437:             std::string_view((const char *)contents.data(), contents.size()));
438:         break;
439:       }
440:       default: {
441:         printf("Error: Invalid segment type: %u\n", segment.type);
442:         abort();
443:       }
444:       }
445:     }
446:   }
447: 
448:   for (const auto [id, entry] : feather.loaded_segments) {
449:     if (entry->name.empty()) {
450:       feather.root = entry;
451:       return feather;
452:     }
453:   }
454: 
455:   printf("Error: No filesystem root found\n");
456:   abort();
457: }
